Q: Why are authentication cookies not flowing from Blazor web assembly to SignalR? A: <p>I don't understand why, but not awaiting <code>hubConnection.StartAsync();</code> solved the issue. The connection is now being stablished as expected.</p>
<p>⚠️ fails:</p>
<pre><code>protected override async Task OnInitializedAsync()
{
    hubConnection = new HubConnectionBuilder()
        .WithUrl(NavigationManager.ToAbsoluteUri(&quot;/match&quot;))
        .WithAutomaticReconnect()
        .Build();

    await hubConnection.StartAsync();
}
</code></pre>
<p>✅ works:</p>
<pre><code>protected override async Task OnInitializedAsync()
{
    hubConnection = new HubConnectionBuilder()
        .WithUrl(NavigationManager.ToAbsoluteUri(&quot;/match&quot;))
        .WithAutomaticReconnect()
        .Build();

    hubConnection.StartAsync();
}
</code></pre>
<p>✅ works:</p>
<pre><code>protected override void OnInitialized()
{
    hubConnection = new HubConnectionBuilder()
        .WithUrl(NavigationManager.ToAbsoluteUri(&quot;/match&quot;))
        .WithAutomaticReconnect()
        .Build();

    hubConnection.StartAsync();
}
</code></pre>
<p>✅ works:</p>
<pre><code>private bool started = false;

protected override async Task OnAfterRenderAsync(bool firstRender)
{
    if (firstRender &amp;&amp; !started)
    {
        hubConnection = new HubConnectionBuilder()
            .WithUrl(NavigationManager.ToAbsoluteUri(&quot;/match&quot;))
            .WithAutomaticReconnect()
            .Build();

        await hubConnection.StartAsync();

        started = true;
    }
}
</code></pre>
